const EXTERNAL_ASSET_ORIGIN = "https://www.liftosaur.com";

export function AssetUrl_external(path: string): string {
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  return `${EXTERNAL_ASSET_ORIGIN}${normalizedPath}`;
}

export function AssetUrl_normalizeExternal(path?: string): string | undefined {
  if (!path) {
    return undefined;
  }
  if (path.startsWith("/externalimages/")) {
    return AssetUrl_external(path);
  }
  return path;
}
